-- DEVINE — données initiales (fichier généré : npm run db:seed:generate)
-- Aucune coordonnée, aucun horaire ni aucune mention légale n'est inventé :
-- ces champs restent vides et se renseignent dans l'administration.

on conflict (id) do nothing;

on conflict (slug) do nothing;

on conflict (slug) do nothing;

on conflict (slug) do nothing;

on conflict (slug) do nothing;

select question, answer, sort_order, is_published from (values
  ('Comment préparer ma visite ?', 'Portez le soutien-gorge que vous mettez le plus souvent, même s''il ne vous convient plus tout à fait : il nous aide à comprendre ce qui va et ce qui ne va pas. Choisissez un haut facile à enlever, et prévoyez un peu de temps.', 10, true),
  ('Comment savoir quelle est ma taille ?', 'La taille indiquée sur une étiquette ne dit pas tout : elle varie selon les marques, les modèles et l''évolution de votre corps. Le plus fiable est d''essayer, avec quelqu''un qui sait observer la tenue d''une bande et d''un bonnet. C''est exactement ce que nous faisons en boutique.', 20, true),
  ('Comment se déroule un conseil personnalisé ?', 'On commence par échanger sur vos habitudes et ce que vous recherchez. Nous vous proposons ensuite plusieurs modèles et plusieurs tailles à essayer en cabine, à votre rythme. On ajuste, on compare, et vous décidez. Il n''y a aucune obligation d''achat.', 30, true),
  ('Quels univers trouve-t-on en boutique ?', 'Lingerie femme, lingerie homme, nuit et homewear, maillots de bain, chaussettes et accessoires. La sélection évolue au fil des collections et des saisons.', 40, true),
  ('Y a-t-il de la lingerie pour homme ?', 'Oui. L''univers masculin a toute sa place chez DEVINE, avec des sous-vêtements choisis pour leur coupe, leurs matières et leur confort.', 50, true),
  ('Comment contacter la boutique ?', 'Par téléphone aux horaires d''ouverture, avec le formulaire de la page Contact, ou tout simplement en passant nous voir.', 60, true)
) as seed (question, answer, sort_order, is_published)
where not exists (select 1 from public.faqs);
