insert into public.services (slug, title, summary, sort_order, is_published) values
  ('conseil-personnalise', 'Conseil personnalisé', 'Nous prenons le temps de comprendre vos habitudes, vos envies et ce qui vous gêne, pour vous orienter vers les bons modèles.', 10, true),
  ('choix-des-tailles', 'Accompagnement au choix des tailles', 'Les tailles varient d''une marque à l''autre : nous vous aidons à trouver la vôtre, modèle par modèle.', 20, true),
  ('essayage', 'Essayage', 'Essayer plusieurs modèles et plusieurs tailles, comparer, prendre son temps : c''est en cabine que tout se joue.', 30, true),
  ('solutions-morphologie', 'Des solutions adaptées à votre morphologie', 'Grands bonnets, petits dos, besoin de maintien ou de légèreté : nous cherchons avec vous les coupes qui vous conviennent.', 40, true),
  ('commandes-particulieres', 'Commandes particulières', 'Un modèle ou une taille absent du stock ? Nous pouvons étudier une commande auprès de la marque.', 50, false)
insert into public.faqs (question, answer, sort_order, is_published)
